1	package netdiag
2	
3	import (
4		"context"
5		"net/netip"
6		"slices"
7		"strings"
8		"testing"
9	
10		"github.com/charmbracelet/x/ansi"
11	
12		"github.com/anthnel/devdesk/internal/command"
13		"github.com/anthnel/devdesk/internal/netcheck"
14		"github.com/anthnel/devdesk/internal/nettrace"
15		"github.com/anthnel/devdesk/internal/ui/components"
16		"github.com/anthnel/devdesk/internal/ui/keymap"
17		"github.com/anthnel/devdesk/internal/ui/testutil"
18	)
19	
20	// DEVDESK-471 step 1 (red phase): the trace sub-level (StateTrace) becomes
21	// self-sufficient. H on the Local route row opens it without tracing, enter
22	// starts or restarts the trace, ctrl+o opens "Trace from", esc cancels then
23	// goes back to where the user came from. The Path tab is gone as of step 2; these
24	// tests name no API that does not exist yet (the "ready" state is
25	// read through isTraceReady); they fail on behaviour.
26	
27	// isTraceReady is the "ready" state of the plan (target known, nothing sent):
