159				{Key: "esc", Description: "Close"},
160			}
161		}
162		off := !pm.launchable().Enabled()
163		source := shortcut.Shortcut{Key: pathSourceKey, Description: "Trace from…", Disabled: !pm.sourceChoosable().Enabled()}
